from pathlib import Path


def replace_once(path, old, new):
    file = Path(path)
    text = file.read_text(encoding='utf-8')
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{path}: expected one anchor, found {count}')
    file.write_text(text.replace(old, new, 1), encoding='utf-8')

replace_once(
    'crates/medusa-agent/src/lib.rs',
    'mod verification;\npub mod verification_dag;\nmod verification_authority;\n',
    'mod verification;\npub mod verification_dag;\nmod verification_schedule;\nmod verification_authority;\n',
)

replace_once(
    'crates/medusa-agent/src/verification_authority.rs',
    '''use crate::verification::{\n    ExecutedVerificationCommand, VerificationResult, execute_verification_command,\n    required_browser_verification,\n};\n''',
    '''use crate::{\n    verification::{\n        ExecutedVerificationCommand, VerificationResult, required_browser_verification,\n    },\n    verification_dag::VerificationReceipt as DagReceipt,\n    verification_schedule::{dag_for_plan, execute_command_wave},\n};\n''',
)

old = '''    let mut checks = Vec::with_capacity(plan.checks.len());\n    let mut browser_material: Option<CheckMaterial> = None;\n\n    for (check_index, check) in plan.checks.iter().enumerate() {\n        let material = match check.kind {\n            VerificationCheckKind::ArtifactSemantic => semantic_material(\n                repo,\n                repository_fingerprint,\n                commit,\n                &plan.components,\n                &store,\n                &mut artifacts,\n                &mut reads,\n                &mut records,\n            )?,\n            VerificationCheckKind::BrowserBehavior | VerificationCheckKind::Accessibility => {\n                if let Some(material) = browser_material.clone() {\n                    material\n                } else {\n                    let material = browser_material_for(\n                        repo,\n                        repository_fingerprint,\n                        commit,\n                        &store,\n                        &mut artifacts,\n                        &mut reads,\n                        &mut records,\n                    )?;\n                    browser_material = Some(material.clone());\n                    material\n                }\n            }\n            _ => command_material(\n                repo,\n                repository_fingerprint,\n                commit,\n                check,\n                &store,\n                &mut artifacts,\n                &mut reads,\n                &mut commands,\n                &mut records,\n            )?,\n        };\n        let mut details = material.details;\n        details.push(format!(\"planner_reason={}\", check.reason));\n        if check_index == 0 {\n            details.extend(graph_details.iter().cloned());\n        }\n        checks.push(VerificationCheckReceipt::new(\n            check,\n            material.passed,\n            material.command,\n            material.evidence_ids,\n            material.artifact_ids,\n            details,\n        ));\n    }\n'''
new = '''    let mut dag = dag_for_plan(repo, commit, &plan)?;\n    let mut materials = BTreeMap::<String, CheckMaterial>::new();\n    let mut browser_material: Option<CheckMaterial> = None;\n\n    while materials.len() < plan.checks.len() {\n        let ready_ids = dag\n            .ready_nodes()\n            .into_iter()\n            .map(|node| node.id.clone())\n            .collect::<Vec<_>>();\n        if ready_ids.is_empty() {\n            return Err(invalid(\"verification DAG has no runnable nodes\"));\n        }\n        let ready_checks = ready_ids\n            .iter()\n            .filter_map(|id| plan.checks.iter().find(|check| check.id == *id))\n            .collect::<Vec<_>>();\n        let mut command_results = execute_command_wave(repo, &ready_checks);\n\n        for check in ready_checks {\n            dag.mark_running(&check.id).map_err(invalid)?;\n            let material = match check.kind {\n                VerificationCheckKind::ArtifactSemantic => semantic_material(\n                    repo, repository_fingerprint, commit, &plan.components, &store,\n                    &mut artifacts, &mut reads, &mut records,\n                )?,\n                VerificationCheckKind::BrowserBehavior | VerificationCheckKind::Accessibility => {\n                    if let Some(material) = browser_material.clone() {\n                        material\n                    } else {\n                        let material = browser_material_for(\n                            repo, repository_fingerprint, commit, &store, &mut artifacts,\n                            &mut reads, &mut records,\n                        )?;\n                        browser_material = Some(material.clone());\n                        material\n                    }\n                }\n                _ => match command_results.remove(&check.id) {\n                    Some(Ok(executed)) => materialize_command(\n                        repository_fingerprint, commit, check, executed, &store, &mut artifacts,\n                        &mut reads, &mut commands, &mut records,\n                    )?,\n                    Some(Err(error)) => rejected_material(error),\n                    None => rejected_material(format!(\n                        \"verification check {} has no executable adapter\", check.id\n                    )),\n                },\n            };\n            let input = dag\n                .node(&check.id)\n                .ok_or_else(|| invalid(format!(\"missing verification DAG node {}\", check.id)))?\n                .input\n                .clone();\n            dag.record_receipt(DagReceipt {\n                node_id: check.id.clone(),\n                input,\n                passed: material.passed,\n                duration_ms: material.command.as_ref().map_or(0, |receipt| receipt.duration_ms),\n                artifact_refs: material.artifact_ids.iter().map(ToString::to_string).collect(),\n            })\n            .map_err(invalid)?;\n            materials.insert(check.id.clone(), material);\n        }\n    }\n\n    let mut checks = Vec::with_capacity(plan.checks.len());\n    for (check_index, check) in plan.checks.iter().enumerate() {\n        let material = materials\n            .remove(&check.id)\n            .ok_or_else(|| invalid(format!(\"missing verification material for {}\", check.id)))?;\n        let mut details = material.details;\n        details.push(format!(\"planner_reason={}\", check.reason));\n        details.push(\"verification_execution=dependency-dag\".to_owned());\n        if check_index == 0 {\n            details.extend(graph_details.iter().cloned());\n        }\n        checks.push(VerificationCheckReceipt::new(\n            check, material.passed, material.command, material.evidence_ids, material.artifact_ids,\n            details,\n        ));\n    }\n'''
replace_once('crates/medusa-agent/src/verification_authority.rs', old, new)
